  "20": {"20": {"title": "Salle des Anciens", "description": "La salle est petite et rectangulaire, avec un sol vieilli et des marquages de cercles rituels et de glyphes runiques. La faible lumière qui pénètre à travers les voûtes délavées révèle des piliers massifs qui soutiennent le plafond. Des cercles rituels et des glyphes runiques sont gravés dans le sol, tandis que des têtes de mort et des tentacules ornent les murs. Le mobilier ancien est dispersé autour de l'espace, ajoutant à l'atmosphère mystérieuse et menaçante. L'eau stagnante recouvre une partie du sol, rendant l'endroit dangereux. Cette salle semble être un lieu de rituels ou de culte, avec des traces de pièges dissimulés dans les coins sombres.", "tags": ["rituels", "culte", "salle", "vieillie", "mystérieuse"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels", "glyphes runiques"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et menaçante", "roomPurpose": "salle de rituels ou de culte", "csvDescription": "Salle", "tileNumber": 20}}}
