  "21": {"21": {"title": "Salle des Rituels", "description": "Cette petite salle rectangulaire, faiblement éclairée, semble avoir été utilisée pour des réunions ou des cultes. Les murs vieillis sont ornés de cercles rituels, et un grand pilier central soutient le plafond. Au centre de la pièce, une table avec une chaise est disposée, comme si quelqu'un venait de s'asseoir pour une réunion importante. Les sols sont marqués de cercles rituels, et les piliers sont ornés de têtes de mort, ajoutant une atmosphère mystérieuse à l'endroit. La pièce semble avoir été abandonnée depuis longtemps, mais les cercles rituels et les têtes de mort laissent entrevoir des pratiques obscures qui y ont eu lieu.", "tags": ["rituel", "salle", "cercles rituels", "têtes de mort", "vieillie"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "table avec chaise", "wallDecorations": ["tête de mort"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table", "chaise"], "creaturesOrTraces": [], "exits": [], "hazards": ["cercles rituels"], "atmosphere": "mystérieuse", "roomPurpose": "salle de réunion ou de culte", "csvDescription": "Salle avec table et chaises", "tileNumber": 21}}}
