  "23": {"23": {"title": "Salle Sacrée des Anciens", "description": "La salle est immense, de forme rectangulaire, et éclairée par une faible lumière qui se répand doucement à travers les colonnes massives. La moiteur de l'air y est perceptible, et des croix sont gravées sur le sol, marquant un chemin qui semble conduire à un point central sombre. Des tentacules noirs, minces et sinistres, semblent émerger des murs, ajoutant une atmosphère de mystère et de malaise. Un autel, simple mais solennel, occupe le centre de la pièce, entouré de colonnes robustes. Des spirales mystérieuses sont gravées sur le sol, indiquant un passage à prendre avec prudence. La salle est un sanctuaire ancien, où les anciens pratiquaient des rituels sacrés.", "tags": ["salle sacrée", "anciens", "tentacules", "rituels", "colonne"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "dim", "condition": "damp", "centralFeature": "dark square", "wallDecorations": ["tentacles"], "floorMarkings": ["crosses"], "architecturalDetails": ["pillars"], "objectsOrFurniture": ["altar"], "creaturesOrTraces": ["tentacles"], "exits": ["door"], "hazards": ["spiral markings"], "atmosphere": "mysterious", "roomPurpose": "sacred chamber", "csvDescription": "Salle avec petite sanctuaire et colonne", "tileNumber": 23}}}
