  "26": {"26": {"title": "Canal d'Eau Sacré", "description": "Le canal d'eau sacré s'inscrit dans un rectangle ancien, ses murs de pierre lisses et usés par le temps. La lumière tamisée émane des torches anciennes plantées ici et là, éclairant les spirales et les lignes gravées sur le sol. Des colonnes et des piliers massifs soutiennent le pont au-dessus du canal, dont les pierres sont usées par l'humidité et le temps. Des tentacules et des têtes de mort ornent les murs, ajoutant une atmosphère mystérieuse et ancienne à l'endroit. Des meubles anciens sont disséminés ici et là, laissant entrevoir des secrets enfouis. Le canal, rempli d'eau trouble, semble vivre d'une vie propre, et des créatures énigmatiques peuvent parfois être aperçues dans son eau. Les murs sont parsemés de cercles rituels, et l'air est chargé d'une odeur ancienne et sacrée. Le canal d'eau sacré est un lieu de passage, mais aussi un lieu de pouvoir et de mystère.", "tags": ["canal", "eau", "murs", "pont", "sacré"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "dim", "condition": "ancient", "centralFeature": "altar", "wallDecorations": ["tentsacles", "heads of death"], "floorMarkings": ["spirals", "lines"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["furniture"], "creaturesOrTraces": ["creatures"], "exits": ["none"], "hazards": ["enchanted", "ancient"], "atmosphere": "mysterious", "roomPurpose": "sacré", "csvDescription": "Canal d'eau entre 2 murs avec pont", "tileNumber": 26}}}
,
  "27": {"27": {"title": "Salle des Cercles", "description": "Dans cette petite salle rectangulaire, la lumière faible éclaire les murs vieillis. Des cercles rituels marquent le sol, et des piliers massifs soutiennent le plafond. Une statue massive, probablement en pierre, domine le centre de la pièce, sur une table ancienne. Des traces de pas indiquent que quelqu'un a récemment visité ce lieu. L'air est humide, et l'eau stagnante s'accumule dans les coins. La porte ouverte au fond laisse entrevoir un autre espace, mais l'entrée semble bloquée par une barrière invisible.", "tags": ["statue", "cercles rituels", "piliers", "salle de rituel", "vieillie", "humide"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["traces de pas"], "exits": ["porte ouverte"], "hazards": ["eau stagnante"], "atmosphère": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "Salle avec statue", "tileNumber": 27}}}
