  "33": {"33": {"title": "Chambre des Sacrifices", "description": "La salle est immense, de forme rectangulaire, avec des murs décrépits et des colonnes massives qui soutiennent le plafond voûté. La lumière tamisée émane des fenêtres étroites, révélant des spirales mystérieuses gravées dans le sol. Des inscriptions anciennes, difficiles à déchiffrer, sont visibles sur les murs. Des tentacules et des trophées ornent les murs, témoignant d'une ancienne civilisation. Un autel sombre et une table en bois sont placés au centre de la pièce, entourés de symboles énigmatiques. Un murmure sinistre flotte dans l'air, et une présence fantomatique plane dans l'ombre. Un secret se cache derrière une porte dissimulée, et des pièges et du gaz toxique risquent de vous accueillir si vous vous approchez trop près. L'atmosphère est oppressante et étrangement fascinante, comme si la pièce avait gardé un secret millénaire.", "tags": ["ritual chamber", "ancient symbols", "mysterious inscriptions", "ghostly presence", "hidden door"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "dim", "condition": "dilapidated", "centralFeature": "unknown", "wallDecorations": ["tentsacles", "trophies"], "floorMarkings": ["spiral patterns", "inscription"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["altar", "table"], "creaturesOrTraces": ["ghostly presence"], "exits": ["hidden door"], "hazards": ["traps", "poison gas"], "atmosphere": "mysterious and eerie", "roomPurpose": "ritual chamber", "csvDescription": "Salle", "tileNumber": 33}}}
,
  "34": {"34": {"title": "Le Couloir des Anciens", "description": "Le couloir s'inscrit dans un mur de pierre brute, éclairé par la faible lumière du jour qui filtre à travers une ouverture étroite au bout du couloir. Les murs sont ornés de tentacules sculptés, rappelant les créatures marines les plus sombres. Des glyphes anciens gravés dans le sol indiquent un chemin à suivre, mais leur signification reste un mystère. Des colonnes massives soutiennent le plafond, ajoutant à l'ambiance sinistre. Un grand autel, orné de tentacules, se dresse au bout du couloir, semblant être le point d'arrivée de ce passage. La humidité qui imprègne l'air rend l'atmosphère oppressante, et l'eau qui coule au sol indique que le couloir est en fait un passage souterrain. Les murs sont recouverts de tapisseries représentant des créatures marines, ajoutant à l'atmosphère mystérieuse et sacrée de ce lieu. Les tentacules sculptés et les glyphes anciens indiquent que ce couloir est lié à des forces anciennes et potentiellement dangereuses.", "tags": ["couloir", "anciens", "tentaclés", "sacré", "humidité"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural", "condition": "damp", "centralFeature": "altar", "wallDecorations": ["tentsacles"], "floorMarkings": ["glyphs"], "architecturalDetails": ["pillars"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["none"], "exits": ["none"], "hazards": ["water"], "atmosphere": "mysterious", "roomPurpose": "sacred", "csvDescription": "Couloir", "tileNumber": 34}}}
,
  "35": {"35": {"title": "Salle des Cercles Rituels", "description": "La salle est carrée, mesurant 35x35 pieds, et semble avoir été utilisée pour des rituels anciens. Le sol est couvert de cercles rituels, dont l'un, particulièrement visible, est entouré d'un œil dessiné au sol. La lumière est faible, émanant de sources inconnues, et la salle est vieillie, avec des piliers massifs qui soutiennent le plafond. Des traces de vieillissement sont visibles sur les murs, et des têtes de mort et des tentacules sont gravés dans le mur, ajoutant une atmosphère sinistre à l'endroit. Des meubles anciens sont dispersés un peu partout, et une porte murée est visible à l'extrémité de la salle. L'eau stagnante est présente dans un coin, rendant l'endroit dangereux. La salle semble être le cœur d'un ancien sanctuaire, où des rituels sombres étaient pratiqués.", "tags": ["rituel", "ancien", "salle", "cercles", "œil"], "sourceFeatures": {"roomSize": "35x35", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": [], "exits": ["porte murée"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel ancien", "csvDescription": "Salle avec œil dessiné au sol", "tileNumber": 35}}}
,
  "36": {"36": {"title": "Couloir des Anciens", "description": "Le couloir des Anciens est étroit et sinistre, ses murs de pierre vieillie sont parsemés de têtes de mort et de tentacules qui semblent sortir du mur. Des cercles rituels et des glyphes runiques gravés dans le sol émettent une faible lumière, révélant des piliers et des statues qui semblent garder un secret millénaire. Le mobilier ancien, usé par le temps, est disséminé ici et là, ajoutant à l'atmosphère mystérieuse et ancienne. Un seul passage mène à l'abîme, où l'eau stagnante semble attendre les intrus. Les anciens rituels qui se déroulaient ici sont désormais oubliés, mais les pièges anciens sont toujours prêts à s'activer.", "tags": ["couloir", "rituels anciens", "têtes de mort", "tentacules"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels", "glyphes runiques"], "architecturalDetails": ["piliers", "statues"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges anciens"], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et ancienne", "roomPurpose": "salle de culte", "csvDescription": "Couloir", "tileNumber": 36}}}
