  "37": {"37": {"title": "Salle avec Trou", "description": "La salle est immense, de forme rectangulaire, avec un plafond voûté qui laisse filtrer une lumière naturelle à travers un grand trou dans le mur. La pièce est recouverte d'une couche de mousse épaisse, qui s'agrippe aux pierres humides et aux murs couverts de mousse. Un grand cercle de pierre, lisse et lisse, occupe le centre de la pièce, entouré d'un motif de spirale gravé dans le sol. Des colonnes massives soutiennent le plafond, et un tableau est posé contre le mur, accroché à une tente suspendue. Un vieux bureau en bois est placé près du mur, laissant entrevoir un espace étroit qui semble mener à un autre endroit. La mousse et les algues ont colonisé les parois, créant une atmosphère mystérieuse et ancienne. Cette pièce semble avoir été utilisée pour des rituels, comme en témoigne la présence du grand cercle central.", "tags": ["rituel", "mystère", "ancien", "salle", "mousse"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural light from window", "condition": "damp and mossy", "centralFeature": "large circular object", "wallDecorations": ["tented wall hanging"], "floorMarkings": ["spiral pattern"], "architecturalDetails": ["pillars"], "objectsOrFurniture": ["table"], "exits": ["window"], "hazards": ["mossy floor"], "atmosphere": "mysterious and ancient", "roomPurpose": "ritual chamber", "csvDescription": "Salle avec trou", "tileNumber": 37}}}
,
  "38": {"38": {"title": "Salle des Sables Lumineux", "description": "La salle est petite et rectangulaire, éclairée par la lumière naturelle qui filtre à travers une ouverture au plafond. Les sols sont marqués de cercles rituels, et les murs sont ornés de reliefs sculptés représentant des figures mystérieuses. Un autel se dresse au centre de la pièce, entouré de piliers robustes. Des tonneaux, remplis d'un liquide mystérieux, sont alignés contre le mur, émettant une lumière douce. Le sol est recouvert d'un tapis de sable qui scintille sous la lumière du soleil magique. La salle semble être un lieu de rituel, mais un piège attend les intrus. L'atmosphère est mystérieuse et l'endroit semble être un passage vers un autre monde.", "tags": ["Salle", "Soleil Magique", "Tonneaux", "Rituels", "Mystère"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "naturelle", "condition": "bonne", "centralFeature": "neurone", "wallDecorations": ["reliefs sculptés"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["autel"], "creaturesOrTraces": [], "exits": [], "hazards": ["piège"], "atmosphere": "mystérieuse", "roomPurpose": "salle de rituel", "csvDescription": "Salle avec soleil magique et tonneaux", "tileNumber": 38}}}
,
  "39": {"39": {"title": "Salle des Rituels Sacrés", "description": "Cette petite salle rectangulaire, faiblement éclairée, semble avoir été utilisée pour des rituels anciens. Les murs vieillis sont ornés de têtes de mort et de tentacules, rappelant les anciens cultes. Au centre de la pièce, un autel est entouré de cercles rituels gravés dans le sol. Des piliers massifs soutiennent le plafond, et une table trône au fond de la pièce. Un squelette, probablement celui d'un ancien initiateur, repose au coin, ajoutant à l'atmosphère sinistre. Une fenêtre permet une faible lumière, et l'eau stagnante dans un coin de la pièce est un danger à ne pas négliger. Cette salle, bien qu'obscure, semble avoir été le cœur des anciens rituels.", "tags": ["rituel", "ancien", "salle", "sacrifice", "squelette"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["squelette"], "exits": ["fenêtre"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "Salle avec lit", "tileNumber": 39}}}
