  "41": {"41": {"title": "Passage Sacré", "description": "Le passage sacré s'inscrit dans un mur de pierre ancienne, érodée par le temps et les éons. Sa largeur impressionnante et sa forme rectangulaire invitent à l'exploration. La lumière naturelle filtre à travers des fissures minuscules, créant un éclairage tamisé qui souligne les motifs de spirales et de croix gravés sur le sol. Des colonnes massives, sculptées de motifs complexes, soutiennent le plafond, ajoutant à l'atmosphère mystérieuse. Un grand autel, orné de tentes et de crânes, occupe le centre du passage, symbolisant un espace de culte ancien. Des hatch marks marquent le sol, peut-être des traces d'anciens rituels. Le passage est silencieux, mais on peut sentir une présence ancienne qui plane dans l'air. Les murs sont parsemés de tapisseries et de peintures murales représentant des figures énigmatiques. Les dangers potentiels sont nombreux, avec des pièges dissimulés dans les ombres et des sortes de tentacules qui pourraient surgir de nulle part. Le passage sacré est un lieu de culte, mais aussi un piège mortel.", "tags": ["Passage", "Ancien", "Sacré", "Mystère", "Pièges"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural", "condition": "ancient", "centralFeature": "altar", "wallDecorations": ["tents", "skulls"], "floorMarkings": ["spiral patterns", "hatch marks"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["none"], "exits": ["none"], "hazards": ["traps"], "atmosphere": "mysterious", "roomPurpose": "sacred space", "csvDescription": "Couloir", "tileNumber": 41}}}
,
  "42": {"42": {"title": "Passage des Anciens", "description": "Le passage est étroit et sinueux, taillant son chemin à travers les roches. Les murs, usés par le temps, sont recouverts de peintures sombres et de symboles énigmatiques. Des cercles rituels marquent le sol, évoquant une ancienne cérémonie. Des piliers massifs soutiennent le plafond, leurs surfaces vieillies par les siècles. Le passage est faiblement éclairé, la lumière filtrant à travers des fissures minuscules. Des traces de créatures étranges sont visibles sur le sol, comme si des êtres mystérieux avaient parcouru ce chemin il y a longtemps. Les murs sont ornés de têtes de mort et de tentacules, ajoutant à l'atmosphère menaçante. Le passage semble mener à un endroit plus profond, mais les sorties sont fermées par des portes massives et des barrières anciennes. Les anciens rituels qui ont eu lieu ici semblent avoir laissé des pièges anciens, prêts à se déclencher à tout moment.", "tags": ["Passage", "Anciens", "Rituels", "Mystérieux", "Menace"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["traces de créature"], "exits": [], "hazards": ["pièges anciens"], "atmosphere": "mystérieuse et menaçante", "roomPurpose": "salle de rituel ou de culte", "csvDescription": "Couloir", "tileNumber": 42}}}
,
  "43": {"43": {"title": "Couloir des Sacrifices", "description": "Le couloir est étroit et sinistre, ses murs rectangulaires sont recouverts de têtes de mort et de cercles rituels. La faible lumière qui pénètre à travers la fenêtre à l'extrémité semble émaner d'une source obscure. Les piliers massifs, vieillis par le temps, supportent le plafond qui semble prêt à s'effondrer. Sur le sol, des cercles rituels sont gravés, marquant le passage de rituels anciens. Un autel, délabré, se dresse au centre du couloir, son autel est recouvert de sang séché. L'eau stagnante au fond du couloir semble être un obstacle à franchir avec prudence. L'atmosphère sinistre et oppressante est accentuée par les murmures lointains qui parviennent jusqu'aux oreilles des explorateurs. Le couloir semble être le passage vers un lieu sacré, mais aussi un lieu de sacrifice.", "tags": ["rituel", "sacrifice", "couloir", "têtes de mort", "cercles rituels"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "squelette", "wallDecorations": ["têtes de mort"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["autel"], "creaturesOrTraces": [], "exits": ["fenêtre"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "Couloir", "tileNumber": 43}}}
,
  "44": {"44": {"title": "Couloir des Anciens", "description": "Le couloir s'enfonce dans l'obscurité, ses murs vieillis et fissurés témoignant de l'âge et de l'abandon. Les piliers massifs, usés par le temps, supportent le plafond qui craque sous le poids. Des cercles rituels émaillent le sol, leurs motifs anciens et énigmatiques évoquant des forces obscures. Des têtes de mort, sculptées avec une finesse inhumaine, sont accrochées aux murs, ajoutant une note macabre à l'atmosphère lugubre. Le mobilier ancien, délabré, semble avoir été abandonné depuis des siècles, ses meubles usés et ses tissus déchirés. L'unique sortie semble menacer un abîme, où l'eau stagnante reflète les ombres qui hantent ce lieu. La faible lumière qui pénètre à travers les fissures ajoute à l'ambiance mystérieuse et ancienne, faisant de ce couloir un lieu de culte ou de rituel, où les anciens pratiquaient leurs cérémonies et leurs sacrifices.", "tags": ["couloir", "anciens", "rituel", "macabre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": [], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphère": "mystérieuse et ancienne", "roomPurpose": "salle de culte ou de rituel", "csvDescription": "Couloir", "tileNumber": 44}}}
,
  "45": {"45": {"title": "Couloir des Anciennes Marques", "description": "Le couloir étroit et sinistre, avec ses murs décrépits et ses sols marqués de spirales et de croix, semble avoir été abandonné depuis des siècles. Les colonnes et les piliers, autrefois robustes, sont maintenant érodés par le temps et la poussière. L'atmosphère est oppressante, et un écho lointain semble résonner dans les profondeurs du couloir. Des tentacules et des trophées étranges ornent les murs, ajoutant à l'ambiance mystérieuse. Un autel sombre se dresse au fond, et un objet mystérieux repose sur une table en ruine. Les marques sur le sol semblent indiquer un passage ancien, peut-être un rituel ou une ancienne voie sacrée. Les échos et les ombres dans ce couloir sont si profonds qu'ils semblent vouloir avaler tout ce qui s'aventure ici. Les créatures inconnues qui pourraient se cacher dans les recoins les plus sombres sont un danger réel.", "tags": ["couloir", "rituel", "ancien", "trophées", "tentacules"], "sourceFeatures": {"roomSize": "large", "roomShape": "irregular", "lighting": "dim", "condition": "dilapidated", "centralFeature": "unknown", "wallDecorations": ["tentsacles", "trophies"], "floorMarkings": ["spiral patterns", "cross shapes"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["altar", "mysterious object"], "creaturesOrTraces": ["unknown creatures"], "exits": ["none visible"], "hazards": ["traps", "enchantments"], "atmosphere": "mysterious and eerie", "roomPurpose": "ritualistic or ancient", "csvDescription": "Couloir (avec numéro 46)", "tileNumber": 45}}}
