  "51": {"51": {"title": "Couloir des Os", "description": "Le couloir étroit et sinistre est recouvert de couches d'os, les ossements se détachant des murs et du plafond avec une étrange lenteur. Les piliers de pierre sont usés et recouverts de croûtes de calcaire, tandis que des cercles rituels émaillent le sol, marquant un passage ancien. La faible lumière qui pénètre à travers une petite ouverture au bout du couloir éclaire les os et les ombres qui les entourent, créant un spectacle d'horreur. Des têtes de mort et des tentacules émergent des murs, ajoutant une touche d'effrayante réalité à l'atmosphère sinistre. Un squelette, probablement ancien, repose au fond du couloir, son crâne dégoulinant de sang séché. La porte à l'extrémité semble légèrement ouverte, révélant un espace sombre et inconnu. L'eau stagnante au sol rend le passage glissant et dangereux.", "tags": ["couloir", "os", "rituel", "squelette", "têtes de mort"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["squelette"], "exits": ["porte ouverte"], "hazards": ["eau stagnante"], "atmosphère": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "Couloir avec des os", "tileNumber": 51}}}
,
  "52": {"52": {"title": "Couloir des Sacrifices", "description": "Le couloir s'enfonce dans l'obscurité, ses murs rectangulaires et vieillis par le temps se reflétant faiblement dans l'eau stagnante qui s'accumule au fond. Des cercles rituels sont gravés au sol, marquant le passage de rituels anciens. Des piliers massifs soutiennent le plafond, leurs surfaces usées par le temps. À l'extrémité du couloir, un autel sombre attire l'œil, orné de têtes de mort et de tentacules qui semblent émerger de l'ombre. Un sang coagulé tache le sol près de l'autel, rappelant les sacrifices passés. Un simple table est posée contre le mur, sans objet apparent. L'atmosphère sinistre est accentuée par l'humidité et l'obscurité qui règne dans ce lieu de rituel ancien.", "tags": ["rituel", "sacrifice", "couloir", "obscurité", "têtes de mort"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["sang"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "couloirs", "tileNumber": 52}}}
