  "60": {"60": {"title": "Salle des Serpents", "description": "La salle est petite et irrégulière, éclairée par une faible lumière qui se répand à peine à travers les piliers et les colonnes vieillies. Le sol est marqué de cercles rituels et de glyphes runiques, qui semblent avoir été dessinés par un ancien maître de rituels. Des serpents, dessinés avec une précision surprenante, serpentent sur le sol, ajoutant une touche de mystère à l'atmosphère déjà sombre. Des meubles anciens sont disséminés un peu partout, témoignant de l'ancienneté de ce lieu. Un autel, orné de têtes de mort et de tentacules, se dresse au centre de la pièce, évoquant une ambiance de sacrifice et de puissance ancienne. Des pièges sont dissimulés dans les recoins, prêts à s'activer à la moindre intrusion. Une fenêtre permet une vue sur une eau stagnante qui semble attendre son heure pour se réveiller.", "tags": ["rituel", "sacrifice", "serpent", "vieillie"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels", "glyphes runiques"], "architecturalDetails": ["piliers", "colonnnes"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": ["fenêtre"], "hazards": ["eau stagnante"], "atmosphère": "mystérieuse et menaçante", "roomPurpose": "salle de rituels", "csvDescription": "Salle avec colonnes et un serpent dessiné au sol", "tileNumber": 60}}}
,
  "61": {"61": {"title": "Couloir des Barils Sacrés", "description": "Le couloir étroit est flanqué de barils de bois massif, leurs anciennes peintures écaillées révélant des motifs de spirales et de croix gravés dans le bois. Les murs, ornés de tentacules et de têtes de mort, semblent témoigner d'une ancienne civilisation. Des colonnes massives soutiennent le plafond, et des spirales et des croix marquent le sol. Un autel de pierre se dresse au bout du couloir, entouré d'un tableau de fleurs étranges. La lumière naturelle filtre à travers une petite ouverture au fond, révélant une atmosphère mystérieuse et sacrée. Des enchantements subtils flottent dans l'air, rendant l'endroit plus que simplement ancien.", "tags": ["couloir", "barils", "sacrés", "ancien", "mystérieux"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural", "condition": "ancient", "centralFeature": "altar", "wallDecorations": ["tentsacles", "heads of death"], "floorMarkings": ["spirals", "cross"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["owl", "flower"], "exits": ["door"], "hazards": ["enchantments"], "atmosphere": "mysterious", "roomPurpose": "sacred", "csvDescription": "Couloir avec des barils", "tileNumber": 61}}}
