  "65": {"65": {"title": "Salle des Rituels", "description": "La salle est petite et triangulaire, avec un sol vieilli et des marquages de cercles rituels au sol. Les murs sont recouverts de tentures sombres, et des piliers massifs soutiennent le plafond. Des petites pierres et des champignons poussent sur le sol, ajoutant une touche d'authenticité à l'atmosphère sinistre. La lumière est faible, filtrant à travers des fenêtres étroites, ce qui rend l'endroit encore plus mystérieux. Des têtes de mort et des tentacules sont suspendus aux murs, rappelant les anciens rituels qui se déroulaient ici. L'endroit est vieilli, avec des traces de vieilles pierres et de champignons qui ont poussé au fil du temps. L'eau stagnante dans un coin ajoute une touche de danger à ce lieu de rituel ancien.", "tags": ["rituel", "salle", "vieillie", "têtes de mort", "tentacules"], "sourceFeatures": {"roomSize": "petite", "roomShape": "triangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["tenture"], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "Salle avec des petites pierres ou champignon", "tileNumber": 65}}}
