  "66": {"66": {"title": "Couloir des Anciens", "description": "Le couloir des Anciens est étroit et sinistre, ses murs vieillis et recouverts de têtes de mort et de tentacules. Des cercles rituels marquent le sol, et des piliers majestueux soutiennent le plafond. Le mobilier ancien est disséminé ici et là, ajoutant à l'atmosphère lugubre. La lumière est faible, rendant l'endroit encore plus menaçant. À chaque pas, l'air semble pesant, et l'eau stagnante au fond du couloir révèle des indices de rituels anciens. La porte murée à l'extrémité semble être le seul moyen de quitter ce lieu sinistre.", "tags": ["couloir", "rituels", "têtes de mort", "tentacules", "anciens"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": ["porte murée"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "couloir", "tileNumber": 66}}}
,
  "67": {"67": {"title": "Couloir des Anciens", "description": "Le couloir s'enfonce dans l'obscurité, ses murs irréguliers et vieillis par le temps. La faible lumière qui filtre à travers les fissures révèle des cercles rituels et des glyphes runiques gravés dans le sol. Des piliers et des colonnes, usés par le temps, soutiennent le plafond qui menace de s'effondrer. Un autel, ancien et mystérieux, se dresse au fond du couloir, son existence évoquant des secrets profonds. L'eau stagnante au sol ajoute à l'atmosphère lugubre et mystérieuse de ce lieu. Seul un passage étroit mène à l'entrée de la salle des rituels, où les anciens cultes se déroulaient peut-être. Les murs sont ornés de têtes de mort et de tentacules, rappelant les créatures qui pourraient se cacher dans les recoins obscurs. La présence de ces éléments rend le couloir un lieu à la fois fascinant et effrayant, où chaque pas peut révéler un nouveau danger.", "tags": ["couloir", "rituel", "ancien", "mystère", "sécrétion"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel ou mobilier", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels", "glyphes runiques"], "architecturalDetails": ["piliers", "colonne"], "objectsOrFurniture": ["autel"], "creaturesOrTraces": [], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et ancienne", "roomPurpose": "salle de rituel ou de culte", "csvDescription": "couloir", "tileNumber": 67}}}
,
  "68": {"68": {"title": "Couloir des Anciens", "description": "Le couloir des Anciens est étroit et sinistre, ses murs de pierre vieillie sont parsemés de têtes de mort et de tentacules qui semblent sortir du mur. Des cercles rituels émaillent le sol, marquant le passage d'anciennes cérémonies. Les piliers massifs, usés par le temps, soutiennent le plafond voûté qui semble menacer de s'effondrer à tout moment. Le mobilier ancien, délabré, est disséminé le long du couloir, ajoutant à l'atmosphère lugubre. L'unique sortie semble menacer une eau stagnante, un piège ancien qui pourrait sembler inoffensif mais qui cache des dangers mortels. La faible lumière qui pénètre à travers les fissures du plafond éclaire les murs et les objets, révélant des traces de sang séché qui semblent avoir été récemment nettoyées. La présence mystérieuse et menaçante de ce couloir semble indiquer qu'il est le passage vers des secrets anciens et dangereux.", "tags": ["couloir", "anciens", "rituels", "têtes de mort", "tentacules"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges anciens"], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphère": "mystérieuse et menaçante", "roomPurpose": "salle de rituels", "csvDescription": "couloir", "tileNumber": 68}}}
,
  "69": {"69": {"title": "Les Voies Énigmatiques", "description": "Les deux couloirs s'entrecroisent comme des tentacules, leurs murs rugueux et décrépits témoignant d'années d'abandon. Des croix et des spirales gravées dans le sol évoquent des rites anciens, mais leur signification reste un mystère. Les colonnes et les piliers, érodés par le temps, semblent vouloir soutenir un passé glorieux. Des tentacules et des trophées étranges ornent les murs, ajoutant une touche de surnaturel à l'atmosphère lugubre. Les couloirs s'élargissent et s'effilochent, offrant de multiples sorties, mais chacune semble mener à un autre mystère. Les murs, délavés, révèlent des traces de peintures énigmatiques, et les sols, marqués de croix et de spirales, semblent inviter à l'exploration. Les couloirs, bien qu'irréguliers, sont vastes et offrent un espace suffisant pour se déplacer. Les lumières tamisées et les ombres qui dansent ajoutent une ambiance de mystère et de danger潜伏在每个角落。", "tags": ["couloir", "mystère", "ancien", "tentacules", "rituel"], "sourceFeatures": {"roomSize": "large", "roomShape": "irregular", "lighting": "dim", "condition": "dilapidated", "centralFeature": "unknown", "wallDecorations": ["tentsacles", "trophies"], "floorMarkings": ["spiral patterns", "crosses"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["unknown"], "creaturesOrTraces": ["unknown"], "exits": ["unknown"], "hazards": ["unknown"], "atmosphere": "mysterious", "roomPurpose": "unknown", "csvDescription": "2 couloirs séparés", "tileNumber": 69}}}
,
  "70": {"70": {"title": "Couloir des Anciens", "description": "Le couloir des Anciens est étroit et sinistre, ses murs de pierre vieillie sont parsemés de têtes de mort et de tentacules qui semblent surgir du néant. Des cercles rituels émaillent le sol, marquant le passage d'anciennes puissances. Les piliers massifs, usés par le temps, soutiennent le plafond qui menace de s'effondrer. Le mobilier ancien, délabré, est disséminé ici et là, ajoutant à l'atmosphère lugubre. L'unique sortie semble menacer un abîme, mais l'eau stagnante qui s'accumule au fond du couloir rend l'endroit dangereux. La faible lumière qui pénètre à travers les fissures dans le plafond éclaire les murs et les objets, révélant des traces de rituels anciens. La présence de pièges anciens rend ce passage particulièrement menaçant pour les explorateurs non avertis.", "tags": ["couloir", "rituels anciens", "têtes de mort", "tentacules"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges anciens"], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et menaçante", "roomPurpose": "salle de rituels", "csvDescription": "couloir", "tileNumber": 70}}}
