  "71": {"71": {"title": "Salle des Tentacules", "description": "La salle est immense, de forme rectangulaire, avec des murs décrépits et des colonnes massives qui semblent avoir été sculptées par les mains de l'oubli. La lumière tamisée pénètre à travers des fenêtres brisées, créant des ombres danseuses sur le sol couvert de spirales mystérieuses. Des tentacules émergent de la terre, se balançant lentement comme des serpents vivants. Des têtes de mort, étranges et déformées, sont suspendues aux murs, des yeux vides fixant le vide. Des objets étranges, inconnus, sont disséminés un peu partout, semblant avoir été laissés là par des créatures oubliées. Un murmure lointain et sinistre résonne dans l'air, et une présence fantomatique plane dans l'angle sombre de la pièce. Un seul passage, dissimulé derrière un rideau de toile, semble mener à un autre monde. Les tentacules et les têtes de mort semblent être les gardiens de cette salle sacrée, prêts à attaquer tout intrus qui ose approcher.", "tags": ["salle", "tentacules", "têtes de mort", "sacré", "mystère"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "dim", "condition": "dilapidated", "centralFeature": "altar", "wallDecorations": ["tentsacles", "heads of death"], "floorMarkings": ["spiral patterns"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["mysterious objects"], "creaturesOrTraces": ["ghostly presence"], "exits": ["hidden door"], "hazards": ["traps"], "atmosphere": "mysterious and eerie", "roomPurpose": "sacred chamber", "csvDescription": "salle", "tileNumber": 71}}}
,
  "72": {"72": {"title": "Couloir des Anciens", "description": "Le couloir s'élargit lentement, révélant une largeur de trente pieds. Sa forme rectangulaire est marquée par des murs lisses et humides, recouverts de mousse verte qui s'agrippe aux pierres. La lumière naturelle filtre à travers de petites fenêtres au plafond, éclairant les spirales mystérieuses gravées dans le sol. Des colonnes croisées soutiennent le plafond, leurs formes évoquant des symboles anciens. Un grand pilier central domine le couloir, orné de tentes suspendues aux murs, ajoutant une touche de mystère à l'atmosphère. Un tableau avec le numéro 72 repose sur une table en bois, son existence ajoutant une note de mystère. À l'horizon, une seule sortie semble visible, menant à l'inconnu. Le sol est glissant et recouvert de mousse, rendant le passage dangereux. Le couloir est un lieu ancien et mystérieux, où les rituels anciens sont peut-être encore pratiqués.", "tags": ["rituel", "mystère", "ancien", "couloir"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural light from windows", "condition": "damp and mossy", "centralFeature": "central pillar", "wallDecorations": ["tented wall hangings"], "floorMarkings": ["spiral patterns"], "architecturalDetails": ["cross-shaped pillars"], "objectsOrFurniture": ["table with number 72"], "creaturesOrTraces": ["tentacles"], "exits": ["one visible exit"], "hazards": ["mossy floor"], "atmosphere": "mysterious and ancient", "roomPurpose": "ritual chamber", "csvDescription": "couloir", "tileNumber": 72}}}
,
  "73": {"73": {"title": "Salle des Anciens", "description": "Dans cette petite salle carrée, la lumière faible et la poussière qui danse dans l'air donnent une ambiance mystérieuse et ancienne. Les murs vieillis sont ornés de têtes de mort et de tentacules, rappelant les anciens rituels qui se déroulaient ici. Des cercles rituels marquent le sol, et des piliers robustes soutiennent le plafond. Un coffre en bois sombre et un baril de cuir sont posés au centre de la pièce, semblant attendre leur ouverture. L'eau stagnante dans un coin de la salle ajoute à l'atmosphère lugubre. Cette salle était autrefois un lieu de rituels, mais aujourd'hui, elle semble abandonnée et mystérieuse.", "tags": ["rituels", "anciens", "salle", "coffre", "baril"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": [], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et ancienne", "roomPurpose": "salle de rituels", "csvDescription": "Salle avec un coffre et un baril", "tileNumber": 73}}}
,
  "74": {"74": {"title": "Les Couloirs Sacrés", "description": "Les deux couloirs séparés s'ouvrent dans un espace immense et ancien, éclairé par la lumière naturelle qui filtre à travers les fissures du plafond. Les parois sont ornées de colonnes massives et de pilastres sculptés, témoignant de l'âge et de la grandeur de ce lieu. Des spirales mystérieuses marquent le sol, guidant les explorateurs vers l'avenir. Des tentacules et des têtes de mort, symboles de la mort et de la vie, sont suspendus aux murs, ajoutant une atmosphère étrange et menaçante à l'endroit. Les couloirs sont dépourvus d'issues, mais un enchantement tisse un spiral enchanté au centre de l'un d'eux, prête à engloutir ceux qui s'y aventurent. Les murs sont recouverts de peintures anciennes, et des meubles étranges sont disséminés dans les coins, laissant entrevoir des secrets millénaires. L'endroit est un sanctuaire, un lieu de culte ancien, où les anciens pratiquaient des rituels sacrés.", "tags": ["couloir", "ancien", "sacré", "mystère", "rituel"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural", "condition": "ancient", "centralFeature": "altar", "wallDecorations": ["tentsacles", "heads of death"], "floorMarkings": ["spirals"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["mobilier"], "creaturesOrTraces": ["traces of ancient creatures"], "exits": ["none"], "hazards": ["enchanted spiral"], "atmosphere": "mysterious and eerie", "roomPurpose": "sacred chamber", "csvDescription": "2 couloirs séparés", "tileNumber": 74}}}
