  "77": {"77": {"title": "Salle des Sacrifices", "description": "La salle est petite et rectangulaire, avec un sol vieilli et des marquages de cercles rituels au sol. La lumière est faible, émanant d'une source inconnue, ce qui ajoute à l'atmosphère sinistre de la pièce. Des piliers massifs soutiennent le plafond, et une table sombre est placée au centre de la pièce. L'ambiance est oppressante, accentuée par les têtes de mort et les tentacules qui semblent émerger des murs. L'endroit semble avoir été un lieu de rituel ancien, et l'eau stagnante au sol indique qu'il a été abandonné depuis longtemps. La porte à l'extrémité de la pièce semble être la seule issue, mais elle est fermée et verrouillée.", "tags": ["rituel", "sacrifice", "vieillie", "sinistre", "abandonnée"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": [], "exits": ["porte"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "salle", "tileNumber": 77}}}
