  "80": {"80": {"title": "Salle des Caisses", "description": "La salle est petite et rectangulaire, avec un sol vieilli et des murs qui ont vu le mieux de leur temps. La faible lumière qui pénètre à travers une fenêtre brisée éclaire des cercles rituels gravés au sol. Des piliers massifs soutiennent le plafond, et une table avec l'inscription '80' est placée au centre de la pièce. Des caisses empilées contre le mur sud semblent remplies de mystères inexplorés. L'atmosphère est mystérieuse et ancienne, comme si cette salle avait été utilisée pour des rituels ou des cultes lointains. L'eau stagnante dans un coin de la pièce ajoute à l'ambiance lugubre. Les caisses, les piliers et les cercles rituels sont les éléments clés de ce lieu, qui semble avoir été oublié depuis longtemps.", "tags": ["rituel", "salle", "caisses", "mystère", "vieillie"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table avec inscription '80'"], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et ancienne", "roomPurpose": "salle de rituel ou de culte", "csvDescription": "Salle avec des caisses", "tileNumber": 80}}}
