  "83": {"83": {"title": "Salle des Sacrifices", "description": "La salle est petite et carrée, avec des murs vieillis et usés. Des cercles rituels marquent le sol, et des piliers soutiennent le plafond. Un autel central, orné de tentacules et de têtes de mort, domine la pièce. Une table est placée près de l'autel, et une fenêtre permet une faible lumière. L'atmosphère est sinistre et ancienne, évoquant des sacrifices passés. L'eau stagnante dans un coin ajoute à l'ambiance lugubre. La seule issue est une fenêtre qui semble être la seule voie pour quitter cette salle sans issue.", "tags": ["rituel", "sacrifice", "tête de mort", "tentacules", "salle sans issue"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "fenêtre", "condition": "vieille et usée", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["monstre"], "exits": ["fenêtre"], "hazards": ["eau stagnante"], "atmosphere": "sinistre et ancien", "roomPurpose": "salle de rituel", "csvDescription": "Salle sans issue", "tileNumber": 83}}}
