  "84": {"84": {"title": "Salle des Tentacules", "description": "La salle est petite et rectangulaire, avec un sol vieilli et des marquages de cercles rituels sur le sol. La lumière est faible, ce qui ajoute à l'atmosphère mystérieuse et menaçante de la pièce. Des piliers et des colonnes ornent les murs, et un tableau avec le chiffre 84 est accroché au mur. Des tentacules émergent de l'eau stagnante qui recouvre le sol, et des têtes de mort sont suspendues aux murs. La salle semble être un lieu de rituel ou de sacrifice, avec des traces de pièges dissimulés dans les coins. Les tentacules semblent vivants et prêts à attaquer.", "tags": ["rituel", "sacrifice", "tentacules", "salle", "mystérieuse"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers", "colonnnes"], "objectsOrFurniture": ["tableau avec le chiffre 84"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et menaçante", "roomPurpose": "salle de rituel ou de sacrifice", "csvDescription": "Salle avec une tentacule", "tileNumber": 84}}}
