  "92": {"92": {"title": "Couloir des Anciens", "description": "Le couloir s'enfonce dans l'obscurité, ses murs vieillis et recouverts de têtes de mort et de tentacules. Des cercles rituels marquent le sol, évoquant une ancienne cérémonie. Les piliers majestueux soutiennent le plafond, tandis que des traces de mobilier ancien sont disséminées le long du passage. L'atmosphère sinistre est accentuée par l'eau stagnante qui s'accumule au fond de la salle, rendant l'endroit encore plus menaçant. Sans issue visible, le couloir semble mener à un destin inconnu.", "tags": ["couloir", "rituels", "têtes de mort", "tentacules", "salle des anciens"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "Couloir avec une salle (sans issue)", "tileNumber": 92}}}
