  "94": {"94": {"title": "L'autel des Tentacules", "description": "Vous pénétrez dans une grande salle rectangulaire, éclairée par une faible lumière qui se répand doucement à travers les arches. L'atmosphère est humide et mystérieuse, comme si la salle avait été abandonnée depuis des siècles. Le sol est marqué de spirales et de hachures, qui semblent indiquer un ancien rituel. Des colonnes majestueuses soutiennent le plafond, et des statues de pierre gardent les arches d'entrée. Au centre de la pièce, un autel colossal est sculpté de tentacules et de formes étranges, comme si une créature marine géante avait tenté de s'implanter ici. Des têtes sculptées de créatures étranges ornent les murs, ajoutant à l'atmosphère sinistre. Les spirales sur le sol pourraient être des pièges, prouvant que cette salle est un lieu sacré et dangereux. Les arches d'entrée permettent d'accéder à d'autres parties du donjon, mais la porte est fermée par une barrière de pierre. La salle est silencieuse, mais vous pouvez sentir une présence ancienne et malveillante qui plane dans l'air.", "tags": ["salle sacrée", "rituel ancien", "tentacules", "autel", "salle mystérieuse"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "dim", "condition": "damp", "centralFeature": "large stone altar", "wallDecorations": ["tented tentacles", "sculpted heads"], "floorMarkings": ["spiral patterns", "hachures"], "architecturalDetails": ["pillars", "arched doorways"], "objectsOrFurniture": ["stone statues"], "creaturesOrTraces": ["no visible creatures"], "exits": ["arched doorways"], "hazards": ["spiral patterns might be traps"], "atmosphere": "mysterious and ancient", "roomPurpose": "sacred chamber or ritual site", "csvDescription": "Autel avec des tentacules et des choses étranges dessinées", "tileNumber": 94}}}
,
  "95": {"95": {"title": "Couloirs Sans Issue", "description": "Vous vous trouvez dans un réseau de couloirs étroits et sinistres, sans issue visible. Les murs sont couverts de peintures sombres et de symboles énigmatiques. Des cercles rituels sont gravés au sol, évoquant une ancienne cérémonie. Des piliers massifs soutiennent le plafond, tandis qu'une table ancienne est posée au centre de la salle. La lumière est faible, émanant d'une source inconnue, et l'atmosphère est oppressante. Des têtes de mort et des tentacules peints sur les murs ajoutent à l'ambiance sinistre. À l'extrémité du couloir, une fenêtre laisse passer une eau stagnante, indiquant un danger potentiel. Les couloirs semblent sans issue, mais une intuition vous pousse à explorer plus avant.", "tags": ["couloir", "salle carrée", "vieillie", "rituel ancien", "sinistre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["squelette"], "exits": ["fenêtre"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel ancien", "csvDescription": "3 couloirs sans issue", "tileNumber": 95}}}
,
  "96": {"96": {"title": "Couloir des Anciens", "description": "Les couloirs étroits et sinueux semblent avoir été sculptés par les mains des dieux. Leur muraille, délabrée et recouverte de tentes, semble avoir été utilisée pour des rituels obscurs. Des motifs de spirales gravés dans le sol indiquent un passage ancien, peut-être un chemin sacré. Les colonnes massives, érodées par le temps, portent le poids de l'histoire. Des meubles brisés et des objets anciens sont éparpillés un peu partout, témoignant de l'activité passée. L'atmosphère est pesante et mystérieuse, comme si les esprits des anciens observaient encore les visiteurs. Des figures fantomatiques flottent dans l'air, ajoutant une note d'effroi à l'ambiance. Les couloirs se perdent dans l'obscurité, et les pièces à l'horizon semblent se multiplier sans fin. Les pièges sont nombreux, prêts à s'activer à la moindre intrusion. Les couloirs des Anciens sont un lieu de peur et de fascination, où l'histoire se mêle à l'obscurité.", "tags": ["couloir", "rituel", "ancien", "obscur", "esprit"], "sourceFeatures": {"roomSize": "large", "roomShape": "irregular", "lighting": "dim", "condition": "dilapidated", "centralFeature": "large stone structure", "wallDecorations": ["tented walls"], "floorMarkings": ["spiral patterns"], "architecturalDetails": ["pillars"], "objectsOrFurniture": ["broken furniture"], "creaturesOrTraces": ["ghostly figures"], "exits": ["none visible"], "hazards": ["traps"], "atmosphere": "mysterious and eerie", "roomPurpose": "ancient ritual chamber", "csvDescription": "couloirs", "tileNumber": 96}}}
