  "97": {"97": {"title": "Salle des Anciens", "description": "La salle est petite et rectangulaire, avec un sol vieilli et des marquages de cercles rituels au sol. La lumière est faible, émanant d'une source inconnue, ajoutant à l'atmosphère sinistre de la pièce. Des piliers massifs soutiennent le plafond, et des statues étranges sont disséminées dans la pièce, ajoutant une touche de mystère. Un autel central, orné de tentacules et de têtes de mort, domine la pièce. Un vieux table est placé près de l'autel, et une porte ouverte permet d'entrer et de sortir. L'eau stagnante dans un coin de la pièce est un danger potentiel. La salle semble être un lieu de rituel ancien, avec des traces de sacrifices et de pratiques obscures.", "tags": ["rituel", "ancien", "sacrifice", "tête de mort", "tentacules"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers", "statues"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["squelette"], "exits": ["porte ouverte"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel ancien", "csvDescription": "salle", "tileNumber": 97}}}
,
  "98": {"98": {"title": "Couloir des Anciens", "description": "Le couloir s'inscrit dans un mur de pierre ancienne, érodée par le temps et les éons. Les murs sont ornés de tentacules et de têtes de mort, symboles de la mort et de la corruption. Des cercles rituels et des glyphes gravés dans le sol évoquent des rituels anciens et mystiques. Des colonnes et des piliers majestueux soutiennent le plafond, tandis qu'un grand autel de pierre se dresse au fond du couloir. Un tableau, posé sur une table en bois, semble être le point central de ce lieu sacré. L'atmosphère est pesante et étrange, comme si le couloir était le passage vers un autre monde. Des apparitions fantomatiques flottent dans l'air, ajoutant à l'ambiance sinistre. Des pièges enchantés sont dissimulés dans les ombres, prêts à s'activer à la moindre intrusion. Le couloir est large et rectangulaire, avec une lumière naturelle qui pénètre à travers des ouvertures minuscules dans le plafond. Les murs sont recouverts de peintures anciennes, et les sols sont marqués de cercles rituels et de symboles mystiques.", "tags": ["couloir", "ancien", "rituel", "sacrifice", "corruption"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural", "condition": "ancient", "centralFeature": "altar", "wallDecorations": ["tentsacles", "heads of death"], "floorMarkings": ["ritual circles", "glyphs"], "architecturalDetails": ["pillars", "columns"], "objectsOrFurniture": ["table"], "creaturesOrTraces": ["ghostly apparitions"], "exits": ["none"], "hazards": ["enchanted traps"], "atmosphere": "mysterious and eerie", "roomPurpose": "sacred chamber", "csvDescription": "couloir", "tileNumber": 98}}}
,
  "99": {"99": {"title": "Couloir des Anciens", "description": "Le couloir des Anciens est étroit et sinistre, ses murs de pierre vieillie sont parsemés de têtes de mort et de tentacules qui semblent sortir du mur. Des cercles rituels émaillent le sol, marquant le passage d'anciennes cérémonies. Les piliers massifs, usés par le temps, soutiennent le plafond voûté qui semble menacer de s'effondrer à tout moment. Le mobilier ancien, délabré, est disséminé le long du couloir, ajoutant à l'atmosphère lugubre. La faible lumière qui filtre à travers les fissures du plafond éclaire les murs et les objets, révélant des traces de sang séché qui semblent avoir été récemment nettoyées. À l'horizon, une porte murée semble être le seul moyen de sortir de ce lieu sinistre. L'eau stagnante qui s'accumule au fond du couloir est un danger à ne pas sous-estimer.", "tags": ["couloir", "rituel", "ancien", "sinistre", "têtes de mort"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": ["porte murée"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel ancien", "csvDescription": "couloir", "tileNumber": 99}}}
,
  "100": {"100": {"title": "Salle des Sacrifices", "description": "La salle est étroite et irrégulière, avec des murs vieillis et des piliers massifs qui soutiennent le plafond. La lumière est faible, filtrant à travers des voiles de poussière. Des cercles rituels sont gravés sur le sol, entourés de dessins étranges et de symboles mystiques. Des barils et des caisses empilées bloquent les sorties, et des pierres les ont été jetées par-dessus. Le mobilier est ancien et délabré, ajoutant à l'atmosphère sinistre de la pièce. L'eau stagnante au fond de la salle rend l'endroit humide et glissant. Les murs sont ornés de têtes de mort et de tentacules, rappelant les sacrifices passés. La salle semble être un lieu de rituels, mais les barils et les pierres bloquent toute issue.", "tags": ["rituel", "sacrifice", "salle", "pierres", "barils", "caisses"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "Salle sans issue (sorties bloquées par des pierres, des barils et des caisses) Dessins sur le sol", "tileNumber": 100}}}
