  "175": {"175": {"title": "Grotte des Champignons", "description": "La grotte est étroite et basse, avec des murs rugueux et des plafonds voûtés. Les lumières tamisées éclairent des champignons géants qui poussent sur les parois et le sol, émettant une odeur de pourriture. Des cercles rituels sont gravés dans le sol, entourant un autel central. Des piliers massifs soutiennent le plafond, et des traces de créatures étranges sont visibles sur le sol. Le mobilier ancien est délabré, et l'atmosphère sinistre est accentuée par l'eau stagnante qui s'accumule dans les coins. La grotte semble avoir été utilisée pour des rituels anciens, et les champignons semblent être une partie intégrante de ces cérémonies.", "tags": ["grotte", "champignons", "rituels", "vieillie", "sinistre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["traces de créatures"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "Grotte avec champignons et champignons", "tileNumber": 175}}}
