  "197": {"197": {"title": "Salle des Sacrifices", "description": "La porte magique se trouve au fond de cette petite salle carrée, éclairée par une faible lumière qui se répand dans l'atmosphère sinistre. Les murs vieillis sont ornés de têtes de mort et de cercles rituels, rappelant l'ancienne vénération des sacrifices. Des piliers robustes soutiennent le plafond, et les cercles rituels marquent le sol. L'air est chargé d'une odeur de vieilles pierres et de mystère. L'eau stagnante au centre de la pièce est un danger à ne pas négliger. Cette salle est destinée à des rituels sacrés, et la porte magique semble être le seul moyen de quitter ce lieu.", "tags": ["porte magique", "salle carrée", "rituels sacrés", "têtes de mort", "cercles rituels"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": [], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "Salle avec porte magique", "tileNumber": 197}}}
