  "198": {"198": {"title": "Salle des Sacrifices", "description": "La porte magique se trouve au fond de cette petite salle carrée, éclairée par une faible lumière qui se répand dans l'atmosphère sinistre. Les murs vieillis sont ornés de têtes de mort et de tentacules, rappelant les anciens rituels qui se déroulaient ici. Des cercles rituels marquent le sol, tandis que des piliers majestueux soutiennent le plafond. La salle est en effet dédiée à des rituels, et les anciens pièges anciens sont toujours prêts à se déclencher. La porte magique, bien que vieillie, semble encore fonctionner, mais elle est entourée de mystère et de malédiction.", "tags": ["porte magique", "salle de rituels", "salle carrée", "vieillie", "sinistre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": [], "creaturesOrTraces": [], "exits": [], "hazards": ["pièges anciens"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "Salle avec porte magique", "tileNumber": 198}}}
