  "199": {"199": {"title": "Salle des Rituels", "description": "La porte magique se trouve au fond de cette petite salle carrée, éclairée par une faible lumière qui se répand à peine. Les murs vieillis sont ornés de têtes de mort et de tentacules, rappelant l'ancienne gloire de ce lieu. Des cercles rituels et des glyphes runiques marquent le sol, tandis que des piliers majestueux soutiennent le plafond. Des meubles anciens sont disséminés un peu partout, ajoutant à l'atmosphère sinistre de la pièce. L'eau stagnante au centre de la salle est un danger à ne pas négliger. Cette salle est dédiée à des rituels obscurs, et la porte magique semble être le seul moyen de quitter ce lieu.", "tags": ["rituels", "porte magique", "salle", "vieillie", "sinistre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels", "glyphes runiques"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "Salle avec porte magique", "tileNumber": 199}}}
