  "224": {"224": {"title": "Salle Sacrificielle Viking", "description": "La salle est immense, rectangulaire et ouverte, avec quatre imposantes colonnes en pierre qui soutiennent un plafond voûté. Le sol est recouvert d'un tapis de mousse verte, et des spirales mystérieuses gravées dans le sol attirent l'œil. Un grand autel de pierre se dresse au centre de la pièce, orné d'un dessin de dragon viking qui semble vivant, ses yeux scintillant d'une lueur étrange. Les murs sont recouverts de peintures anciennes, et des tentacules peints semblent sortir des pierres. L'air est humide et chargé d'une atmosphère ancienne et mystérieuse. Des arches majestueuses permettent d'accéder à d'autres parties du donjon. Les spirales sur le sol sont un piège, et il est préférable de les éviter. La salle est destinée à des sacrifices, et l'atmosphère y est lourde de secrets anciens.", "tags": ["sacrifice", "dragon", "viking", "salle", "mystère"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural light from windows", "condition": "damp and mossy", "centralFeature": "large stone altar", "wallDecorations": ["tentsacles", "skulls"], "floorMarkings": ["spiral patterns"], "architecturalDetails": ["pillars", "archway"], "objectsOrFurniture": ["altar"], "creaturesOrTraces": ["none"], "exits": ["archway"], "hazards": ["spiral patterns"], "atmosphere": "mysterious and ancient", "roomPurpose": "sacrificial chamber", "csvDescription": "Salle ouverte avec 4 colonnes et dessin de dragon viking", "tileNumber": 224}}}
,
  "225": {"225": {"title": "Salle des Cercles Rituels", "description": "Cette petite salle rectangulaire, faiblement éclairée, semble avoir été utilisée pour des rituels. Les murs vieillis sont ornés de têtes de mort et de tentacules, rappelant les anciens cultes. Des cercles rituels sont gravés au sol, entourant une table en bois usée. Des piliers massifs soutiennent le plafond, et l'atmosphère sinistre est accentuée par l'eau stagnante qui s'accumule dans un coin. La salle semble abandonnée depuis longtemps, mais les traces de vieilles cérémonies sont encore visibles.", "tags": ["rituel", "salle", "vieillie", "têtes de mort", "tentacules", "cercles rituels"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["table"], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituel", "csvDescription": "Salle ouverte", "tileNumber": 225}}}
