  "299": {"299": {"title": "Abîme des Cercles Rituels", "description": "Dans l'abîme, un espace rectangulaire et humide, les cercles rituels et les glyphes runiques dessinent des motifs mystérieux sur le sol. Les piliers et colonnes, vieilles et usées, soutiennent une atmosphère sinistre. Le faible éclairage révèle des traces de mobilier ancien, abandonné et délabré. L'humidité pèse sur l'air, et l'eau stagnante menace de vous engloutir. Les cercles rituels semblent attendre un rituel ancien, mais l'abîme est un lieu de ténèbres, où les tentacules et les têtes de mort gardent un secret ancien.", "tags": ["abîme", "rituels", "ténèbres", "mystère", "humidité"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "humide", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels", "glyphes runiques"], "architecturalDetails": ["piliers", "colonnnes"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphère": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "abîme", "tileNumber": 299}}}
