  "396": {"396": {"title": "Salle Sacrificielle Ancienne", "description": "La salle est petite et ronde, éclairée par une faible lumière qui se répand doucement à travers les piliers vieillis. Des cercles rituels marquent le sol, et les murs sont ornés de têtes de mort et de tentacules, ajoutant une atmosphère menaçante. Un autel sacrificiel, posé sur une plateforme, domine la pièce. À l'arrière, une table en pierre supporte un livre et des bougies, éclairant la scène d'une lueur vacillante. Le mobilier ancien et les piliers ajoutent une touche de mystère à cette ancienne salle de rituel. L'eau stagnante dans un coin de la pièce ajoute une touche de danger à l'atmosphère déjà menaçante.", "tags": ["rituel", "ancien", "sacrifice", "mystère", "menace"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rond", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et menaçante", "roomPurpose": "salle de rituel ancien", "csvDescription": "salle ouverte avec un autel sacrificiel sur une plateforme. Table en pierre avec un livre et des bougies à l'arrière de la salle", "tileNumber": 396}}}
