  "397": {"397": {"title": "Salle Circulaire à Système Mécanique", "description": "La salle circulaire est étroite et irrégulière, éclairée par une faible lumière qui se répand dans l'air poussiéreux. Les murs vieillis sont ornés de piliers robustes, et au centre de la pièce, un autel circulaire est entouré de cercles rituels. Des cercles de lumière émergent des murs, semblant indiquer un ancien rituel. Le sol est marqué de symboles anciens, et des objets anciens sont disséminés un peu partout, ajoutant à l'atmosphère mystérieuse et menaçante. Un système mécanique complexe est intégré dans le sol, permettant à un couloir secret de tourner lentement. L'eau stagnante dans un coin de la pièce ajoute à l'ambiance lugubre. La salle semble être un lieu de rituels ou de culte, et le système mécanique pourrait être utilisé pour activer des sorts ou des mécanismes secrets.", "tags": ["rituel", "système mécanique", "salle circulaire", "mystérieuse", "vieillie"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges"], "exits": [], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et menaçante", "roomPurpose": "salle de rituels ou de culte", "csvDescription": "salle circulaire avec un système mécanique pour tourner le couloir (fermé)", "tileNumber": 397}}}
,
  "398": {"398": {"title": "Salle des Anciens", "description": "La salle circulaire est étroite et basse, avec un système mécanique complexe au centre qui permet de tourner le couloir. Les murs sont recouverts de cercles rituels, et les piliers massifs sont ornés de têtes de mort et de tentacules. La lumière faible émane des torches anciennes qui se balancent sur des crochets rouillés. Le sol est marqué de cercles rituels, et des traces de mobilier ancien sont encore visibles. Une porte murée bloque l'entrée, tandis que l'eau stagnante menace de s'infiltrer. L'atmosphère est mystérieuse et ancienne, comme si les murs avaient entendu des milliers d'histoires. Cette salle est dédiée aux rituels, et les anciens l'utilisaient pour invoquer des forces obscures.", "tags": ["rituel", "salle circulaire", "mystère", "vieillie", "têtes de mort"], "sourceFeatures": {"roomSize": "petite", "roomShape": "salle carrée", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges anciens"], "exits": ["porte murée"], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et ancienne", "roomPurpose": "salle de rituels", "csvDescription": "salle circulaire avec un système mécanique pour tourner le couloir (ouverte)", "tileNumber": 398}}}
,
  "399": {"399": {"title": "Salle de Destruction", "description": "La salle de destruction est étroite et irrégulière, avec des pierres et des colonnes qui semblent avoir été jetées hâtivement. La lumière est faible, émanant d'une source inconnue au fond de la pièce. Les murs sont vieillis, marqués de cercles rituels qui semblent avoir été dessinés par un doigt tremblant. Des piliers et des colonnes de pierre sont disséminés un peu partout, certains encore debout, d'autres déjà tombés. Le sol est couvert de mobilier ancien, des meubles usés et délabrés qui semblent avoir été abandonnés depuis longtemps. Une porte murée bloque l'entrée, tandis qu'une eau stagnante s'accumule dans un coin, créant un danger supplémentaire. L'atmosphère est sinistre, accentuée par les murmures lointains et les échos de pas lointains. Cette salle semble avoir été utilisée pour des rituels de destruction, et les cercles rituels sur le sol indiquent qu'elle a été utilisée pour des cérémonies sombres.", "tags": ["salle de destruction", "pierres", "colonnes", "rituels", "sinistre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers", "colonnnes"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["traces de créatures"], "exits": ["porte murée"], "hazards": ["eau stagnante"], "atmosphere": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "salle de destruction avec des pierres, des colonnes", "tileNumber": 399}}}
,
  "400": {"400": {"title": "Salle de Destruction", "description": "La salle de destruction est étroite et irrégulière, avec des pierres et des colonnes qui semblent avoir été jetées hâtivement. La lumière est faible, émanant d'une source inconnue au fond de la pièce. Les murs vieillis montrent des traces de vieilles peintures et des cercles rituels érodés. Le sol est marqué de cercles rituels, et des piliers et colonnes anciennes se dressent à l'intérieur, donnant une impression de vieilles ruines. Des meubles anciens sont dispersés un peu partout, ajoutant à l'atmosphère sinistre de la pièce. Un seul passage mène à l'extérieur, mais l'eau stagnante devant le passage rend l'accès difficile. La salle semble avoir été utilisée pour des rituels, et les tentacules et têtes de mort qui ornent les murs témoignent de la cruauté qui y a eu lieu. Les pièges anciens dissimulés dans les pierres et les colonnes rendent la salle dangereuse pour les explorateurs non avertis.", "tags": ["salle de destruction", "pierres", "colonnes", "rituels", "sinistre"], "sourceFeatures": {"roomSize": "petite", "roomShape": "irrégulière", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers", "colonnnes"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": ["pièges anciens"], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphère": "sinistre", "roomPurpose": "salle de rituels", "csvDescription": "salle de destruction avec des pierres, des colonnes", "tileNumber": 400}}}
