  "401": {"401": {"title": "Salle de labyrinthe des Anciens", "description": "La salle de labyrinthe est petite et rectangulaire, avec un sol vieilli et des marquages de cercles rituels gravés dans le sol. La faible lumière qui pénètre à travers les piliers décrépits éclaire les têtes de mort sculptées dans les murs. Le mobilier ancien est dispersé autour de l'unique sortie, qui semble être la seule issue de cette salle de culte. L'atmosphère est mystérieuse et ancienne, avec un sentiment de vieillesse et d'oubli. L'eau stagnante dans un coin de la salle ajoute à l'ambiance lugubre. Les cercles rituels et les têtes de mort donnent à cette salle un air de mystère et de danger.", "tags": ["labyrinthe", "salle de culte", "anciens", "rituels"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": [], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphere": "mystérieuse et ancienne", "roomPurpose": "salle de culte", "csvDescription": "salle de labyrinthe", "tileNumber": 401}}}
