  "402": {"402": {"title": "Salle de Labyrinthe avec Grille, Boîte et Barils", "description": "La salle de labyrinthe est immense, son plan rectangulaire s'étend sous vos yeux. La lumière naturelle filtre à travers les fenêtres, éclairant les murs humides et couverts de mousse. Des spirales gravées dans le sol vous guident vers le centre de la pièce, où se dresse un grand objet circulaire, mystérieux et imposant. Des colonnes majestueuses soutiennent le plafond, tandis que des fenêtres permettent une vue sur l'extérieur. Les barils, empilés contre le mur, semblent abandonnés depuis des siècles. Un petit monstre, probablement un rat ou un souris, s'agite nerveusement dans un coin, ajoutant une touche d'effroi à l'atmosphère étrange de la pièce. Les tentacules et les têtes de mort ornent les murs, rappelant l'ancien culte qui a peut-être eu lieu ici. Les deux fenêtres offrent une issue, mais la mousse et les racines qui s'y enfoncent rendent l'accès dangereux. Cette salle, avec son labyrinthe, sa grille, sa boîte et ses barils, semble être le cœur d'un rituel ancien, maintenant abandonné.", "tags": ["labyrinthe", "grille", "boîte", "barils"], "sourceFeatures": {"roomSize": "large", "roomShape": "rectangular", "lighting": "natural light from windows", "condition": "damp and mossy", "centralFeature": "large circular object", "wallDecorations": ["tentsacles", "heads of death"], "floorMarkings": ["spirals"], "architecturalDetails": ["pillars", "windows"], "objectsOrFurniture": ["large circular object"], "creaturesOrTraces": ["small creature"], "exits": ["two windows"], "hazards": ["mossy floor"], "atmosphere": "mysterious and eerie", "roomPurpose": "ritual chamber", "csvDescription": "salle de labyrinthe avec grille, boîte et barils", "tileNumber": 402}}}
,
  "403": {"403": {"title": "Salle de Labyrinthe avec Grille", "description": "La salle de labyrinthe avec grille est étroite et rectangulaire, ses murs vieillis et recouverts de cercles rituels. La faible lumière qui pénètre à travers les fissures dans la voûte ajoute à l'atmosphère mystérieuse et menaçante de la pièce. Des piliers et des colonnes soutiennent le plafond, et le mobilier ancien est disséminé un peu partout, ajoutant à l'ambiance vieillie de la pièce. Des cercles rituels marquent le sol, et l'eau stagnante dans un coin de la pièce rend l'atmosphère encore plus menaçante. La grille au centre de la pièce semble être le point focal de cette salle, peut-être un autel ou un point de passage vers un autre monde. Les tentacules et les têtes de mort sont visibles sur les murs, ajoutant une touche d'horreur à l'ensemble. La salle semble être un lieu de rituels ou de culte, et l'endroit est certainement hanté par des forces obscures.", "tags": ["labyrinthe", "grille", "rituels", "mystérieuse", "menaçante"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort", "tentacules"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers", "colonnnes"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": [], "exits": [], "hazards": ["eau stagnante"], "atmosphère": "mystérieuse et menaçante", "roomPurpose": "salle de rituels ou de culte", "csvDescription": "salle de labyrinthe avec grille", "tileNumber": 403}}}
,
  "404": {"404": {"title": "Salle de labyrinthe des Anciens", "description": "La salle de labyrinthe est petite et rectangulaire, avec un sol vieilli et des marquages de cercles rituels qui semblent avoir été dessinés il y a des siècles. La faible lumière qui pénètre à travers les fissures dans les murs accentue l'atmosphère mystérieuse et ancienne de la pièce. Des piliers massifs soutiennent le plafond, et le mobilier ancien est réparti de manière étrange, comme si les anciens cultistes avaient laissé des traces de leur passage. Les têtes de mort sculptées dans les murs ajoutent une touche macabre à l'ambiance, tandis que les cercles rituels évoquent des secrets inexplorés. L'unique sortie mène à un escalier qui descend dans l'abîme, et l'eau stagnante qui s'accumule au fond de la salle est un danger à ne pas négliger. La salle de labyrinthe semble être un lieu de culte, où les anciens pratiquaient des rituels obscurs et sacrés.", "tags": ["labyrinthe", "salle de culte", "rituels", "têtes de mort", "abîme"], "sourceFeatures": {"roomSize": "petite", "roomShape": "rectangulaire", "lighting": "faible", "condition": "vieillie", "centralFeature": "autel", "wallDecorations": ["têtes de mort"], "floorMarkings": ["cercles rituels"], "architecturalDetails": ["piliers"], "objectsOrFurniture": ["mobilier ancien"], "creaturesOrTraces": [], "exits": ["un seul"], "hazards": ["eau stagnante"], "atmosphère": "mystérieuse et ancienne", "roomPurpose": "salle de culte", "csvDescription": "salle de labyrinthe", "tileNumber": 404}}}
